import { defineOnceTool } from "agevex";
import type { FunctionReference } from "convex/server";
import { z } from "zod";

export const TODO_LIMITS = {
  minChars: 1,
  items: 100,
  idChars: 100,
  textChars: 4000,
  listBytes: 32 * 1024,
  scopeChars: 1024,
} as const;

export const todoList = z
  .array(
    z.strictObject({
      id: z.string().min(TODO_LIMITS.minChars).max(TODO_LIMITS.idChars),
      text: z.string().min(TODO_LIMITS.minChars).max(TODO_LIMITS.textChars),
      done: z.boolean(),
    }),
  )
  .max(TODO_LIMITS.items)
  .superRefine((todos, ctx) => {
    if (new Set(todos.map(({ id }) => id)).size !== todos.length)
      ctx.addIssue({ code: "custom", message: "Todo ids must be unique" });
    // A count bound alone allows 100 × 4000 four-byte characters (>1 MiB).
    // Bound serialized UTF-8 as well: the list and its ledger result stay small.
    if (new TextEncoder().encode(JSON.stringify(todos)).byteLength > TODO_LIMITS.listBytes)
      ctx.addIssue({ code: "custom", message: "Todo list exceeds 32 KiB" });
  });

export const todoScope = z.strictObject({
  subject: z.string().min(TODO_LIMITS.minChars).max(TODO_LIMITS.scopeChars),
  threadId: z.string().min(TODO_LIMITS.minChars).max(TODO_LIMITS.scopeChars),
});

type Scope = z.infer<typeof todoScope>;
type Result = { todos: z.infer<typeof todoList> };
export type TodoFunctions = {
  read: FunctionReference<"query", "internal", Scope, Result>;
  write: FunctionReference<"mutation", "internal", Scope & Result, Result>;
};

/** Register on an agevex Agent; the runtime supplies the fenced ToolContext. */
export function createTodoTools(refs: TodoFunctions) {
  const tools = {
    todo_read: defineOnceTool({
      name: "todo_read",
      input: z.strictObject({}),
      run: async (_input, tc) => {
        tc.signal.throwIfAborted();
        return tc.ctx.runQuery(
          refs.read,
          todoScope.parse({ subject: tc.subject, threadId: tc.threadId }),
        );
      },
    }),
    todo_write: defineOnceTool({
      name: "todo_write",
      input: z.strictObject({ todos: todoList }),
      run: async (input, tc) => {
        tc.signal.throwIfAborted();
        const { todos } = z.strictObject({ todos: todoList }).parse(input);
        // Never take an owner or thread from model input. The managed context
        // routes this internal mutation through core's atomic cancellation fence.
        const scope = todoScope.parse({ subject: tc.subject, threadId: tc.threadId });
        return tc.ctx.runMutation(refs.write, { ...scope, todos });
      },
    }),
  };
  tools.todo_read.description =
    "Read this owner's durable thread todo list. Use a new call id for a fresh read.";
  tools.todo_write.description = `Replace this owner's thread todo list with up to ${TODO_LIMITS.items} unique items. The entire serialized UTF-8 list must fit ${TODO_LIMITS.listBytes} bytes. An empty list clears it.`;
  return tools;
}

import { defineSchema, defineTable, type DataModelFromSchemaDefinition } from "convex/server";
import { v } from "convex/values";

/**
 * Spread into the host's defineSchema; no agevex component table is added.
 * Agent 0.7.7 only supports userId/title/summary metadata, so this small host
 * table is necessary: @convex-dev/agent/src/client/threads.ts:18-30,55-63.
 */
export const todoTables = {
  agevexTodos: defineTable({
    subject: v.string(),
    threadId: v.string(),
    todos: v.array(v.object({ id: v.string(), text: v.string(), done: v.boolean() })),
  }).index("by_owner_thread", ["subject", "threadId"]),
};

// A local model keeps this snippet type-safe without importing generated host
// files. A host may freely merge other tables into its own schema.
const schema = defineSchema(todoTables);
export type TodoDataModel = DataModelFromSchemaDefinition<typeof schema>;

import {
  internalMutationGeneric,
  internalQueryGeneric,
  type MutationBuilder,
  type QueryBuilder,
} from "convex/server";
import { v } from "convex/values";
import { todoList, todoScope } from "./todo.js";
import type { TodoDataModel } from "./todoSchema.js";

const query = internalQueryGeneric as QueryBuilder<TodoDataModel, "internal">;
const mutation = internalMutationGeneric as MutationBuilder<TodoDataModel, "internal">;
const scope = { subject: v.string(), threadId: v.string() };
const result = {
  todos: v.array(v.object({ id: v.string(), text: v.string(), done: v.boolean() })),
};

/** Internal only: callers must originate in core's authorized ToolContext. */
export const read = query({
  args: scope,
  returns: v.object(result),
  handler: async (ctx, args) => {
    todoScope.parse(args);
    // One row is <= 32 KiB list + 2 × 1024 × 4 scope bytes + 1 KiB overhead
    // = 41 KiB. unique() reads at most TWO rows (convex/src/server/impl/
    // query_impl.ts:334-343), then rejects duplicates: <= 82 KiB / two docs
    // / one query, far below 16 MiB / 32,000 docs / 4096 queries. Even two
    // host-corrupted 1 MiB documents remain below the transaction read limit.
    const row = await ctx.db
      .query("agevexTodos")
      .withIndex("by_owner_thread", (q) =>
        q.eq("subject", args.subject).eq("threadId", args.threadId),
      )
      .unique();
    return { todos: todoList.parse(row?.todos ?? []) };
  },
});

export const write = mutation({
  args: { ...scope, ...result },
  returns: v.object(result),
  handler: async (ctx, args) => {
    const owner = todoScope.parse({ subject: args.subject, threadId: args.threadId });
    const todos = todoList.parse(args.todos);
    // Same <=82 KiB / two-document read bound as above, plus one <=41 KiB
    // document written (a successful lookup contains at most one row).
    // The indexed read and insert/patch share a transaction, so concurrent
    // first writes cannot create two rows for the same subject and thread.
    const row = await ctx.db
      .query("agevexTodos")
      .withIndex("by_owner_thread", (q) =>
        q.eq("subject", owner.subject).eq("threadId", owner.threadId),
      )
      .unique();
    if (row) await ctx.db.patch("agevexTodos", row._id, { todos });
    else await ctx.db.insert("agevexTodos", { ...owner, todos });
    return { todos };
  },
});
